using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using V15Voice;
public static class SubtitleTests {
 static int count;static void Check(bool ok,string name){if(!ok)throw new Exception(name);Console.WriteLine("PASS "+name);count++;}static bool Fails(Action action){try{action();return false;}catch{return true;}}
 public static void Main(){string temp=Path.Combine(Path.GetTempPath(),"v15_subtitles_"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);var d=new SubtitleDocument{Duration=8,Device="cpu",Model="fixture",Cues=new List<SubtitleCue>{new SubtitleCue{Start=2.125,End=3.5,Text="Hello, world."},new SubtitleCue{Start=5,End=6.5,Text="A second\nline.",Note="Check"}}};string xml=Path.Combine(temp,"result.xml");d.Save(xml);var loaded=SubtitleDocument.Load(xml);Check(loaded.Cues.Count==2&&loaded.Cues[0].Start==2.125&&loaded.Cues[1].Text.Contains("\n"),"XML retains leading silence and internal gaps");Check(loaded.Device=="cpu"&&loaded.Cues[1].Note=="Check","Review notes and device survive reopening");
  string media=Path.Combine(temp,"Mẫu (1).mp4");File.WriteAllText(media,"input fixture");string a=d.ExportBeside(media),b=d.ExportBeside(media);Check(Path.GetFileName(a)=="Mẫu (1).srt"&&Path.GetFileName(b)=="Mẫu (1)_2.srt","Unicode names retained and existing SRT never overwritten");Check(File.ReadAllText(a).Contains("00:00:02,125 --> 00:00:03,500"),"SRT retains measured timestamps");Check(File.ReadAllText(media)=="input fixture","Source media unchanged");Check(SubtitleDocument.Stamp(3661.9996)=="01:01:02,000","Rounding carries correctly");Check(SubtitleDocument.ParseTime("01:01:02,125")==3662.125,"Timestamp editing parses exact milliseconds");Check(Fails(()=>SubtitleDocument.ParseTime("00:60:00,000")),"Invalid minute rejected");
  loaded.Cues[1].Start=3;Check(Fails(()=>loaded.Validate()),"Overlapping cue rejected");loaded.Cues[1].Start=5;loaded.Cues[1].End=9;Check(Fails(()=>loaded.Validate()),"Out of duration cue rejected");loaded.Cues[1].End=Double.NaN;Check(Fails(()=>loaded.Validate()),"NaN rejected");loaded.Cues[1].End=6;loaded.Cues[1].Text=" ";Check(Fails(()=>loaded.Validate()),"Missing speech rejected");loaded.Cues[1].Text="bad --> time";Check(Fails(()=>loaded.Validate()),"Embedded SRT delimiter rejected");File.WriteAllText(xml,"<!DOCTYPE x [<!ENTITY e SYSTEM 'file:///etc/passwd'>]><subtitles duration='2'><cue start='0' end='1'>&e;</cue></subtitles>");Check(Fails(()=>SubtitleDocument.Load(xml)),"External XML entities rejected");
  if(Environment.OSVersion.Platform!=PlatformID.Win32NT){string script=Path.Combine(temp,"fixture.py");File.WriteAllText(script,"import sys,time,base64\nprint('V15_ASR\\t50\\t'+base64.b64encode(b'working').decode(),flush=True)\nif 'cancel' in sys.argv: time.sleep(60)\nif 'fail' in sys.argv: sys.exit(4)\n");int updates=0;using(var p=new SubtitleProcess())p.Run("python3",script,"",(n,m)=>{if(n==50)updates++;});Check(updates>0,"Worker progress delivered");using(var p=new SubtitleProcess())Check(Fails(()=>p.Run("python3",script,"fail",(n,m)=>{})),"Worker failure surfaced");using(var p=new SubtitleProcess()){var task=Task.Run(()=>{try{p.Run("python3",script,"cancel",(n,m)=>{});return false;}catch(OperationCanceledException){return true;}});Thread.Sleep(350);p.Cancel();Check(task.Wait(3000)&&task.Result,"Stop terminates worker promptly");}}
  Console.WriteLine("TOTAL SUBTITLES "+count+" passed.");
 }
}
